sys_variable_value.value:
(function execute(inputs, outputs) {

    try {
        // Get the RITM sys_id from the trigger
        // We need this to find the attachment the manager uploaded
        var ritmSysId = inputs.ritm_sys_id;

        // GlideSysAttachment is the API for reading file attachments
        // in ServiceNow server-side scripts
        var attachment = new GlideSysAttachment();

        // Get all attachments on this RITM record
        // Returns a GlideRecord of sys_attachment records
        var attachmentGR = new GlideRecord('sys_attachment');
        attachmentGR.addQuery('table_name', 'sc_req_item');
        attachmentGR.addQuery('table_sys_id', ritmSysId);
        attachmentGR.addQuery('file_name', 'ENDSWITH', '.csv');
        attachmentGR.orderByDesc('sys_created_on');
        attachmentGR.setLimit(1);
        attachmentGR.query();

        if (!attachmentGR.next()) {
            gs.error('Bulk Workspace Import: No CSV attachment found on RITM ' + ritmSysId);
            outputs.result = 'Error: No CSV file found on the request.';
            outputs.record_count = '0';
            return;
        }

        // Read the raw bytes of the attachment and convert to a string
        var csvContent = attachment.getContent(attachmentGR);

        if (!csvContent) {
            gs.error('Bulk Workspace Import: CSV attachment was empty');
            outputs.result = 'Error: The uploaded CSV file was empty.';
            outputs.record_count = '0';
            return;
        }

        // Split the CSV into lines
        // The first line is the header row — skip it
        var lines = csvContent.split('\n');
        var headers = lines[0].split(',');

        gs.info('Bulk Workspace Import: Found ' + (lines.length - 1) + ' data rows');

        var successCount = 0;
        var errorCount = 0;

        // Loop through each data row (skip header at index 0)
        for (var i = 1; i < lines.length; i++) {
            var line = lines[i].trim();

            // Skip empty lines
            if (!line) continue;

            var values = line.split(',');

            // Insert a row into the staging table
            // Column names match the import set table's u_ prefixed fields
            var staging = new GlideRecord('x_1903615_worksp_0_workspace_records');
            staging.initialize();
            staging.u_workspace_name = values[0] ? values[0].trim() : '';
            staging.u_workspace_type = values[1] ? values[1].trim() : '';
            staging.u_location = values[2] ? values[2].trim() : '';
            staging.u_max_occupancy = values[3] ? values[3].trim() : '0';
            staging.u_status = values[4] ? values[4].trim() : '';
            staging.u_workspace_description = values[5] ? values[5].trim() : '';
            staging.u_image = values[6] ? values[6].trim() : '';

            var stagingSysId = staging.insert();

            if (stagingSysId) {
                successCount++;
            } else {
                errorCount++;
                gs.error('Bulk Workspace Import: Failed to insert row ' + i);
            }
        }

        // Now trigger the transform map to move data from
        // staging table into Workspace Options
        // GlideImportSetTransformerWorker runs the named transform map
        var transformWorker = new GlideImportSetTransformerWorker(
            'x_1903615_worksp_0_workspace_records',  // source table
            'Workspace records'                        // transform map name
        );
        transformWorker.setBackground(false); // run synchronously so we wait for results
        transformWorker.start(null, null);

        gs.info('Bulk Workspace Import: Transform complete. Success: ' + successCount + ', Errors: ' + errorCount);

        // Set outputs so the email step can use them
        outputs.result = 'Import completed. ' + successCount + ' records processed, ' + errorCount + ' errors.';
        outputs.record_count = successCount + '';

    } catch (ex) {
        gs.error('Bulk Workspace Import error: ' + ex.message);
        outputs.result = 'Import failed: ' + ex.message;
        outputs.record_count = '0';
    }

})(inputs, outputs);

